using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Analysis;

internal sealed class ContinuousCutoffCentralizerDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Analysis/ContinuousCutoffCentralizer.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Continuous-cutoff optimality and compressed vector-functional centralization for a positive contraction C in an arbitrary concrete von Neumann algebra N and an arbitrary vector Omega.",
        H("Continuous cutoffs and compressed centralization"), Blocks(
            Node("rangeSupport", "Orthogonal closed-range support", "The orthogonal projection onto the closure of the range of an actual bounded operator. For an algebra element this projection belongs to the same concrete von Neumann algebra: the range closure is invariant under its commutant. For selfadjoint operators its kernel is the original kernel. No measurable functional calculus is used.", false),
            Node("interiorSupport", "Actual interior support", "P is the orthogonal closed-range support of C(1-C). It commutes with C by invariance of both the range closure and the kernel, rather than by an assertion that P is a continuous function of C. The direct identity xi=C xi+(1-C)xi proves the endpoint-kernel decomposition. Every feasible positive X is PXP. Endpoint accumulation, P=0, and the zero Hilbert space remain included.", false),
            Node("overlap", "Continuous spectral overlap", "G_t is the real continuous functional calculus of x maps to min(x,t(1-x)), applied to C. For t>=0 and a positive contraction it is positive, at most C and at most t(1-C), and belongs to the algebra.", false),
            Node("Feasible", "All ambient feasible operators", "X belongs to the concrete von Neumann algebra and satisfies 0<=X, X<=C, and X<=t(1-C). No commutation between X and C is assumed.", false),
            Node("vectorValue", "Fixed vector objective", "The objective is the real part of the original vector coefficient <Omega,T Omega>. The vector may be zero, and its coefficient need not be faithful.", false),
            Node("AllOverlapOptimal", "Simultaneous overlap optimality", "For every real t>0, the actual continuous overlap is feasible and dominates the vector objective of every ambient feasible operator.", false),
            Node("CompressedCentralizes", "Centralization on the interior corner", "For every Y in the algebra, the complex vector coefficients of (PCP)(PYP) and (PYP)(PCP) agree. The corner is specified by actual compressions, without a separate bundled corner or any representation-normality premise.", false),
            Node("compressed_centralization_implies_optimal", "Compressed centralization implies optimality", "Centralization is equivalently centralization of C for the compressed vector P Omega. The norm-closed star subalgebra centralizing that vector contains continuous functions of C, and direct vector convergence places the support of (C-s)+ in it. At s=t/(1+t), positive-part identities give the two exact diagonal overlap formulas. Centralization removes both off-diagonal vector coefficients; compression of the two feasibility inequalities gives the objective bound. Feasible operators are supported on P by the proved endpoint-kernel argument.", true),
            Node("optimal_cutoff_annihilation", "Actual quadratic feasible perturbations", "For selfadjoint E,F in N, any Y in N, and G_t in N, assume u,gamma_E,gamma_F>0 and the three operator margins u(E^2+F^2)<=G_t, gamma_E E^2<=t(1-C)-G_t and gamma_F F^2<=C-G_t. Assume actual optimality of G_t against every feasible X in N. Positive-square Young inequalities show that G_t+epsilon(EYF+(EYF)*)-k epsilon^2(E^2+F^2) is feasible for both signs near zero. Optimality makes its derivative vanish; repeating with iY gives the complex cross coefficient <Omega,EYF Omega>=0. The full criterion constructs these margins explicitly, so they are not supplied as an unproved optimality-to-annihilation assumption.", true),
            Node("optimal_implies_compressed_centralization", "Optimality implies compressed centralization", "Use flat continuous ramps min(1,max(0,(n+1)u-b)). Uniform weighted errors and exact kernel annihilation prove strong convergence to orthogonal range supports. An interior ramp applied to x(1-x), a lower ramp complementary to the positive part (x-s)+, and an upper ramp with b=3 give separated cutoffs at r_n=s+2/(n+1). Their three strict margins follow from scalar inequalities and continuous functional calculus. The lower cutoff retains the entire atom at s. Direct convergence of the two vectors in the inner product gives vanishing threshold cross coefficients, hence threshold centralization for P Omega. For s<=t the positive-part increment is bounded between (t-s) times the two threshold supports. Summing these bounds telescopes; finite support sums approximate C in norm with error at most 1/m. Norm closure gives centralization of C for P Omega, equivalently compressed centralization.", true),
            Node("all_overlap_optimal_iff_compressed_centralizes", "Endpoint-correct two-way operator criterion", "For any complete complex Hilbert space H, any concrete von Neumann algebra N on H, any C in N with 0<=C<=1, and any vector Omega, simultaneous optimality of every actual continuous overlap G_t for t>0 is equivalent to centralization of PCP on PNP for the original vector coefficient. All support projections are constructed in N. No separability, finite dimension, faithfulness, Borel calculus, complete positivity, Stinespring map, or GNS representation normality is assumed. This operator criterion alone does not establish the original full-curvature maximal-hockey versus maximal-f classification: the original continuous-moment supplier and whole-L1 realization bridge are separate obligations.", true),
            Paragraph(Text("The ingredients are standard continuous functional calculus, orthogonal range supports, positive-square inequalities, and continuity of vector coefficients. The proof uses these ingredients directly on arbitrary Hilbert spaces."))
        )));

    private static DocumentBlock Node(string name, string title, string prose, bool theorem) =>
        Describe.Lean(DescribeId.Create("continuouscutoffcentralizer-" + name.Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))),
            theorem ? DescribeRole.Theorem : DescribeRole.Definition);
}
